from threetears.evals import Eval

from footprint import Trip, footprint_kg

def estimate(case):
    """The trip's estimated footprint, in kilograms."""
    return {"kg": footprint_kg(Trip.from_row(case))}


def within_five_percent(case, out):
    """The estimate is within 5% of the audited figure."""
    return abs(out["kg"] - case["audited_kg"]) / case["audited_kg"] <= 0.05 + 1e-9

trips = Eval("data/audited.jsonl", runner=estimate, grader=[within_five_percent], k=1)
